const task=$('Entrada de un seguimiento').first().json;
const raw=$input.first().json || {};
let body=raw.body ?? raw;
if(typeof body==='string'){try{body=JSON.parse(body);}catch{body={};}}
const status=raw.statusCode==null?200:Number(raw.statusCode);
const fail=(motivo,estado='revision')=>[{json:{...task,contacto_valido:false,estado_final:estado,detalle:{motivo}}}];
if(raw.error || status<200 || status>=300 || body.status!=='success') return fail('MANYCHAT_CONTACTO_NO_VERIFICADO');
const c=body.data || {};
if(String(c.id)!==String(task.subscriber_id)) return fail('MANYCHAT_CONTACTO_NO_COINCIDE');
if(c.status!=='active' || c.is_followup_enabled===false) return fail('CONTACTO_INACTIVO_O_SEGUIMIENTO_DESHABILITADO','cancelado');
const channel=task.payload?.canal;
if(channel==='tiktok' && !c.tt_user_id) return fail('CONTACTO_SIN_TIKTOK');
if(channel==='instagram' && !c.ig_id) return fail('CONTACTO_SIN_INSTAGRAM');
if(!['instagram','tiktok'].includes(channel)) return fail('CANAL_NO_CONFIGURADO');
const clean=s=>String(s||'').replace(/\s+/g,' ').trim();
if(clean(c.last_input_text) && clean(task.payload?.ultimo_mensaje_cliente) && clean(c.last_input_text)!==clean(task.payload.ultimo_mensaje_cliente)) return fail('CLIENTE_YA_RESPONDIO','cancelado');
return [{json:{...task,contacto_valido:true}}];

const task=$('Entrada de un seguimiento').first().json;
const raw=$input.first().json || {};let b=raw.body ?? raw;if(typeof b==='string'){try{b=JSON.parse(b);}catch{b={};}}
const status=raw.statusCode==null?200:Number(raw.statusCode);
const ok=!raw.error && status>=200 && status<300 && b.status==='success';
return [{json:{...task,ok,estado_final:ok?'enviado':'revision',detalle:{motivo:ok?'MANYCHAT_ACEPTO_SOLICITUD':'MANYCHAT_CAMPOS_NO_ACEPTADO',http_status:status}}}];

